import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"管理后台配置","description":"默认 :8081。static_dir 磁盘优先于 embed；空字符串关闭 UI。enabled=false 只关管理监听。","frontmatter":{"title":"管理后台配置","description":"默认 :8081。static_dir 磁盘优先于 embed；空字符串关闭 UI。enabled=false 只关管理监听。"},"headers":[],"relativePath":"guide/config/admin.yaml.md","filePath":"guide/config/admin.yaml.md","lastUpdated":1790057721000}`),a={name:`guide/config/admin.yaml.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="管理后台配置" tabindex="-1">管理后台配置 <a class="header-anchor" href="#管理后台配置" aria-label="Permalink to “管理后台配置”">​</a></h1><p>文件：<code>admin.yaml</code>。前缀 <code>KIRIVERS_ADMIN_</code>。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>默认</th><th>说明</th><th>何时改</th></tr></thead><tbody><tr><td><code>addr</code></td><td>string</td><td><code>:8081</code></td><td>监听</td><td>生产绑定 <code>127.0.0.1:8081</code> 或内网</td></tr><tr><td><code>enabled</code></td><td>bool</td><td><code>true</code></td><td><code>false</code> <strong>只关闭管理监听</strong>（无管理 API / SPA / 反代）。客户端平面与 health 仍运行</td><td>只要客户端平面时</td></tr><tr><td><code>mode</code></td><td>string</td><td>示例 <code>debug</code></td><td>与 client 一起决定进程 Gin mode</td><td>生产 <code>release</code></td></tr><tr><td><code>tls_cert</code> / <code>tls_key</code></td><td>path</td><td><code>&quot;&quot;</code></td><td>同时非空才 HTTPS</td><td>管理平面自己终止 TLS 时填写；否则由反代终止</td></tr><tr><td><code>trusted_proxies</code></td><td>string[]</td><td><code>[]</code></td><td>空则不信任 <code>X-Forwarded-For</code></td><td>管理面反代后</td></tr><tr><td><code>static_dir</code></td><td>path</td><td><code>frontend/dist</code></td><td>见下表</td><td>一般保持默认</td></tr></tbody></table><h2 id="管理台静态文件" tabindex="-1">管理台静态文件 <a class="header-anchor" href="#管理台静态文件" aria-label="Permalink to “管理台静态文件”">​</a></h2><p>官方二进制已嵌入管理台。优先级：</p><ol><li><code>static_dir</code> <strong>显式空字符串</strong> → <strong>关闭 UI</strong>（即使嵌入了 <code>index.html</code>）。</li><li>非空 <code>static_dir</code> 且磁盘上有 <code>index.html</code> → 使用磁盘（改 dist 不必重编 Go）。</li><li>否则嵌入 FS 含 <code>index.html</code> → embed。</li><li>二者都没有 → API-only（<code>GET /</code> 为 JSON 404）。</li></ol><p><code>static_dir</code> 指向管理台静态文件（或留空关闭 UI）。文档站 VitePress 产物不是管理台；官方 Releases 二进制已嵌入 UI，不必再拷 <code>frontend/dist</code>。</p><p>生产管理平面会把 <code>/api/v1/projects/**</code> <strong>反代</strong>到本进程客户端平面，供控制台预览 check / integrity。</p>`,8)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};